def _launcher_pid() -> Optional[int]:
    """Verify stable kernel identity, or the unchanged strict legacy epoch guard.

    Single-number records are never trusted. New launches record kernel identity;
    old records are not automatically migrated because their PID may be reused.
    """
    raw = _read(state_dir() / "launcher.pid")
    pid_s, _, born_s = (raw or "").partition(" ")
    if not pid_s.isdigit() or not born_s:
        return None
    if born_s.startswith('linux-v1:'):
        pid = int(pid_s)
        actual = _linux_process_identity(pid)
        return pid if actual is not None and actual == born_s and _pid_alive(pid) else None
    try:
        pid, born = int(pid_s), float(born_s)
    except ValueError:
        return None
    actual = _create_time(pid)
    return pid if actual is not None and abs(actual - born) < 0.01 and _pid_alive(pid) else None

