class _locked:
    """Cross-process critical section over the lease file (fcntl on a sibling lock file)."""

    def __init__(self, path: Path):
        self._lockfile = path.with_suffix(".lock")
        self._fh = None
        self._windows_guard = None

    def __enter__(self):
        if os.name == "nt":
            from tools.bot_desktop.runtime import _flocked
            _private_dir(self._lockfile)
            self._windows_guard = _flocked(self._lockfile)
            self._windows_guard.__enter__()
            return self
        if fcntl is None:
            return self
        _private_dir(self._lockfile)
        self._fh = open(self._lockfile, "a+", encoding="utf-8", opener=_open_private)
        fcntl.flock(self._fh.fileno(), fcntl.LOCK_EX)
        return self

    def __exit__(self, *exc):
        if self._windows_guard is not None:
            return self._windows_guard.__exit__(*exc)
        if self._fh is None:
            return
        fcntl.flock(self._fh.fileno(), fcntl.LOCK_UN)
        self._fh.close()

